interface UserPreferences {
  [key: string]: string | number | boolean
}

// Per-request data: pass `cache: 'no-store'` so this is re-fetched on every
// request instead of being captured once at build time. Without it, fetch
// defaults to `auto no cache`, which statically prerenders the route and would
// serve stale build-time data. (Cache Components is not enabled in this project.)
async function getUserPreferences(): Promise<UserPreferences> {
  const res = await fetch('https://api.example.com/user/preferences', {
    cache: 'no-store',
  })

  if (!res.ok) {
    throw new Error(`Failed to fetch user preferences: ${res.status}`)
  }

  return res.json()
}

export default async function UserDashboard() {
  const preferences = await getUserPreferences()

  return (
    <div>
      <h2>User Dashboard</h2>
      <ul>
        {Object.entries(preferences).map(([key, value]) => (
          <li key={key}>
            {key}: {String(value)}
          </li>
        ))}
      </ul>
    </div>
  )
}

